import math,numpy as np
from scipy.optimize import least_squares
obs={'vase':(466,353),'table':(123,348)}
LM={'vase':(-2.46,1.45),'table':(2.50,1.45)}
def resid(p):
    x,y,h=p; r=[]; hr=math.radians(h)
    for k,(u,v) in obs.items():
        X,Y=LM[k]; dx,dy=X-x,Y-y
        D=dx*math.sin(hr)+dy*math.cos(hr); L=dx*math.cos(hr)-dy*math.sin(hr)
        if D<0.2: D=0.2
        r+=[(u-256)-256*L/D,(v-256)-396.8/D]
    return r
best=None
for h0 in range(0,360,10):
    s=least_squares(resid,[1.14,5.26,h0])
    if best is None or s.cost<best.cost: best=s
print(best.x,'rms',np.sqrt(np.mean(np.array(best.fun)**2)))
x,y,h=best.x; hr=math.radians(h)
def gp(u,v):
    D=396.8/(v-256); L=1.55*(u-256)/(v-256)
    f=(math.sin(hr),math.cos(hr)); rr=(math.cos(hr),-math.sin(hr))
    return (round(x+D*f[0]+L*rr[0],2), round(y+D*f[1]+L*rr[1],2), round(D,2))
print('pot base u241 v448',gp(241,448))
def proj(X,Y):
    dx,dy=X-x,Y-y; D=dx*math.sin(hr)+dy*math.cos(hr); L=dx*math.cos(hr)-dy*math.sin(hr)
    return round(256+256*L/D),round(256+396.8/D),round(D,2)
print('plant(1.22,2.55)',proj(1.22,2.55))
print('cabinet(2.55,3.90)',proj(2.55,3.90))
